    private static void kiemTraPvPThangTheoPhe() throws Exception {
        DichVuBatPacket[] dichVus = new DichVuBatPacket[4];
        ChickenNguoiChoi[] nguoiChois = new ChickenNguoiChoi[4];
        for (int slot = 0; slot < nguoiChois.length; slot++) {
            dichVus[slot] = new DichVuBatPacket();
            nguoiChois[slot] = new ChickenNguoiChoi(dichVus[slot]);
            nguoiChois[slot].ma = 94_100 + slot;
            nguoiChois[slot].ten = "PvpTeam" + slot;
        }

        ChickenChoDau choDau = new ChickenChoDau(
                null, (byte) 0, (byte) 4, (byte) 0);
        ChickenQuanLyChien tran = new ChickenQuanLyChien(
                choDau, nguoiChois, (byte) 0);
        try {
            Field danhSach = ChickenQuanLyChien.class.getDeclaredField(
                    "chienBinhs");
            danhSach.setAccessible(true);
            ChickenChienBinh[] chienBinhs =
                    (ChickenChienBinh[]) danhSach.get(tran);
            Method kiemTraThang = ChickenQuanLyChien.class.getDeclaredMethod(
                    "kiemTraThang");
            kiemTraThang.setAccessible(true);
            Field daKetThuc = ChickenQuanLyChien.class.getDeclaredField(
                    "daKetThuc");
            daKetThuc.setAccessible(true);

            chienBinhs[1].chet = true;
            chienBinhs[1].hp = 0;
            kiemTraThang.invoke(tran);
            dung(!daKetThuc.getBoolean(tran),
                    "PvP ket thuc khi phe le van con slot 3 song");

            chienBinhs[3].chet = true;
            chienBinhs[3].hp = 0;
            kiemTraThang.invoke(tran);
            dung(daKetThuc.getBoolean(tran),
                    "PvP khong ket thuc khi nguoi cuoi phe le da chet");
            for (int slot = 0; slot < dichVus.length; slot++) {
                ChickenTinNhan ketQua = dichVus[slot].layTinCuoi(50);
                khacNull(ketQua,
                        "PvP khong gui ket qua cho slot " + slot);
                DataInputStream doc = new ChickenTinNhan(
                        (byte) 50, ketQua.layDuLieu()).boDoc();
                bang(0, doc.readByte(),
                        "PvP bao sai phe chan thang cho slot " + slot);
            }
        } finally {
            tran.dungBot();
        }
    }

    private static ChickenNguoiChoi taoNguoiChoiNapDan(
            int ma,
            String ten,
            int napDan,
            ChickenMauVatPham mauSung,
            ChickenMauThuocTinhVatPham mauOptionNapDan
    ) {
        ChickenNguoiChoi nguoiChoi =
                new ChickenNguoiChoi(new DichVuBatPacket());
        nguoiChoi.ma = ma;
        nguoiChoi.ten = ten;
        nguoiChoi.wp = 57;
        ChickenVatPham sung = new ChickenVatPham(110);
        sung.mau = mauSung;
        sung.chiSo = 5;
        ChickenThuocTinhVatPham option =
                new ChickenThuocTinhVatPham(14, napDan);
        option.optionTemplate = mauOptionNapDan;
        sung.itemOptions.add(option);
        nguoiChoi.itemBody[5] = sung;
        return nguoiChoi;
    }

    private static void xacNhanPvpKhongBoLuot(
            ChickenQuanLyChien tran,
            ChickenNguoiChoi nguoiChoi,
            Field luot,
            Field dongHo,
            String trangThai
    ) throws Exception {
        byte luotTruoc = luot.getByte(tran);
        int[] napDanTruoc = Arrays.copyOf(
                (int[]) dongHo.get(tran),
                ((int[]) dongHo.get(tran)).length);
        tran.boLuot(nguoiChoi);
        bang(luotTruoc, luot.getByte(tran),
                trangThai + " van bo duoc luot PvP");
        dung(Arrays.equals(napDanTruoc, (int[]) dongHo.get(tran)),
                trangThai + " van sua hang doi nap dan PvP");
    }

    private static void kiemTraCmd79UltronKhongNapNhanh()
            throws Exception {
        dung(!ChickenXacNhanKetThucDan.docVaBoQua(
                        new ChickenTinNhan((byte) 79, new byte[0])),
                "CMD79 rong duoc chap nhan");
        dung(!ChickenXacNhanKetThucDan.docVaBoQua(
                        new ChickenTinNhan((byte) 79, new byte[]{1})),
                "CMD79 thieu toa do duoc chap nhan");
        dung(ChickenXacNhanKetThucDan.docVaBoQua(
                        new ChickenTinNhan((byte) 79, new byte[]{0})),
                "CMD79 khong co diem dung khuon bi tu choi");

        ChickenNguoiChoi ultron =
                new ChickenNguoiChoi(new DichVuBatPacket());
        ultron.ma = 93_110;
        ultron.ten = "ReloadUltron";
        ultron.wp = 57;
        ultron.avenger = ChickenKyNangDacBietUltron.AVG_ULTRON;
        ChickenNguoiChoi doiThu =
                new ChickenNguoiChoi(new DichVuBatPacket());
        doiThu.ma = 93_111;
        doiThu.ten = "ReloadUltronTarget";
        doiThu.wp = 57;

        ChickenQuanLyChien tran = new ChickenQuanLyChien(
                null, new ChickenNguoiChoi[]{ultron, doiThu}, (byte) 0);
        try {
            Field chienBinhsField = ChickenQuanLyChien.class.getDeclaredField(
                    "chienBinhs");
            chienBinhsField.setAccessible(true);
            ChickenChienBinh[] chienBinhs =
                    (ChickenChienBinh[]) chienBinhsField.get(tran);
            ChickenChienBinh ultronTrongTran = chienBinhs[0];
            ultronTrongTran.avenger =
                    ChickenKyNangDacBietUltron.AVG_ULTRON;
            ultronTrongTran.ultronDaGuiMenu = true;
            ultronTrongTran.maVuKhi = 57;
            ultronTrongTran.hp = ultronTrongTran.mauToiDa = 10_000;
            chienBinhs[1].hp = chienBinhs[1].mauToiDa = 10_000;

            Field luot = ChickenQuanLyChien.class.getDeclaredField(
                    "luotHienTai");
            luot.setAccessible(true);
            luot.setByte(tran, (byte) 0);
            dung(tran.kichHoatKyNangUltron(ultron),
                    "khong kich hoat duoc Ultron x3 trong testcase");
            tran.ban(ultron, new ChickenTinNhan(
                    (byte) 22,
                    taoPacket((byte) 0, ultronTrongTran.x,
                            ultronTrongTran.y, (short) 45,
                            30, 0, 1, false)));

            Field daGui = ChickenQuanLyChien.class.getDeclaredField(
                    "ultronX3SoLanDaGui");
            daGui.setAccessible(true);
            Field somNhat = ChickenQuanLyChien.class.getDeclaredField(
                    "ultronX3XacNhanSomNhatMs");
            somNhat.setAccessible(true);
            bang(1, daGui.getInt(tran),
                    "Ultron khong gui dung vien dau");

            somNhat.setLong(tran, System.currentTimeMillis() + 80L);
            tran.kiemTraVaCham(ultron,
                    new ChickenTinNhan((byte) 79, new byte[]{0}));
            bang(1, daGui.getInt(tran),
                    "CMD79 som da mo vien Ultron thu hai");
            Thread.sleep(140L);
            bang(2, daGui.getInt(tran),
                    "CMD79 som bi bo mat, Ultron khong tu gui vien thu hai");

            somNhat.setLong(tran, System.currentTimeMillis() + 80L);
            tran.kiemTraVaCham(ultron,
                    new ChickenTinNhan((byte) 79, new byte[]{0}));
            bang(2, daGui.getInt(tran),
                    "CMD79 som da mo vien Ultron thu ba ngay lap tuc");
            Thread.sleep(140L);
            bang(3, daGui.getInt(tran),
                    "CMD79 som bi bo mat, Ultron khong tu gui vien thu ba");

            somNhat.setLong(tran, System.currentTimeMillis() + 80L);
            tran.kiemTraVaCham(ultron,
                    new ChickenTinNhan((byte) 79, new byte[]{0}));
            Thread.sleep(140L);
            Field ketQua = ChickenQuanLyChien.class.getDeclaredField(
                    "ultronX3KetQua");
            ketQua.setAccessible(true);
            dung(ketQua.get(tran) == null,
                    "Ultron khong dong loat sau khi du ba phat");
        } finally {
            tran.khiNguoiChoiRoi(ultron);
            tran.khiNguoiChoiRoi(doiThu);
            tran.dungBot();
        }
    }

    private static void kiemTraPvpTuChotKhiMatCmd79()
            throws Exception {
        ChickenNguoiChoi nguoiBan =
                new ChickenNguoiChoi(new DichVuBatPacket());
        nguoiBan.ma = 93_112;
        nguoiBan.ten = "PendingShotShooter";
        nguoiBan.wp = 57;
        ChickenNguoiChoi mucTieu =
                new ChickenNguoiChoi(new DichVuBatPacket());
        mucTieu.ma = 93_113;
        mucTieu.ten = "PendingShotTarget";
        mucTieu.wp = 57;

        ChickenQuanLyChien tran = new ChickenQuanLyChien(
                null,
                new ChickenNguoiChoi[]{nguoiBan, mucTieu},
                (byte) 0);
        try {
            Field danhSach = ChickenQuanLyChien.class.getDeclaredField(
                    "chienBinhs");
            danhSach.setAccessible(true);
            ChickenChienBinh[] chienBinhs =
                    (ChickenChienBinh[]) danhSach.get(tran);
            ChickenChienBinh shooter = chienBinhs[0];
            ChickenChienBinh target = chienBinhs[1];
            shooter.hp = shooter.mauToiDa = 1_000;
            target.hp = target.mauToiDa = 1_000;
            Field luot = ChickenQuanLyChien.class.getDeclaredField(
                    "luotHienTai");
            luot.setAccessible(true);
            luot.setByte(tran, (byte) 0);

            Map<ChickenChienBinh, Integer> damage = new HashMap<>();
            damage.put(target, 100);
            ChickenKetQuaDan ketQua = new ChickenKetQuaDan(
                    (byte) 0,
                    shooter.x,
                    shooter.y,
                    (short) 45,
                    (byte) 20,
                    (byte) 20,
                    new short[][]{new short[]{shooter.x}},
                    new short[][]{new short[]{shooter.y}},
                    damage);
            ChickenMayMan.PhienTanCong mayMan =
                    ChickenMayMan.batDau(shooter, chienBinhs);
            mayMan.chuanBiPhongThuTruocPhat(
                    ketQua.satThuongTheoMucTieu.keySet());

            Method batDauCho = ChickenQuanLyChien.class.getDeclaredMethod(
                    "batDauChoKetThucPhatBan",
                    ChickenChienBinh.class,
                    ChickenKetQuaDan.class,
                    ChickenMayMan.PhienTanCong.class);
            batDauCho.setAccessible(true);
            batDauCho.invoke(tran, shooter, ketQua, mayMan);

            Thread.sleep(120L);
            bang(1_000, target.hp,
                    "PvP tru damage truoc animation/timeout");
            bang(0, luot.getByte(tran),
                    "PvP doi luot truoc animation/timeout");

            Thread.sleep(
                    ChickenThoiGianHoatAnhDan.tinh(ketQua) + 120L);
            bang(900, target.hp,
                    "mat CMD79 lam server bo luon damage authoritative");
            dung(luot.getByte(tran) != 0,
                    "mat CMD79 lam tran PvP khoa vinh vien");
        } finally {
            tran.dungBot();
            tran.khiNguoiChoiRoi(nguoiBan);
            tran.khiNguoiChoiRoi(mucTieu);
        }
    }

