            tayDiem.chiSo = 1;
            tayDiem.soLuong = 1;
            nguoiChoi.itemBag[1] = tayDiem;
            nguoiChoi.dungVatPham(new ChickenTinNhan(
                    (byte) 26, new byte[]{1, 1}));
            dung(nguoiChoi.itemBag[1] == tayDiem,
                    "vat pham tay diem bi dung trong tran");
